(function(root){
'use strict';if(!root.document)return;
const t=(ru,en)=>document.documentElement.lang==='en'?en:ru;
const KEY='vertex-profile-v1';let s={translation:true,loadMore:true,mapZoom:false,mapMove:false,notifications:true};
try{s={...s,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}};
const row=(id,ic,ru,en)=>'<button class="vx-menu-row" data-menu="'+id+'"><span class="vx-menu-icon">'+ic+'</span><strong>'+t(ru,en)+'</strong><span class="vx-chevron">›</span></button>';
const back=id=>'<button class="vx-back" data-menu="'+id+'">←</button>';
const sw=(id,ru,en,copyRu,copyEn)=>'<div class="vx-toggle-row"><div><strong>'+t(ru,en)+'</strong><p>'+t(copyRu,copyEn)+'</p></div><button class="vx-switch '+(s[id]?'on':'')+'" data-toggle="'+id+'" role="switch"><span>✓</span></button></div>';
function screen(title,html){modal(title,html);document.getElementById('modal').classList.add('vertex-menu-modal');bind();}
function bind(){document.querySelectorAll('[data-menu]').forEach(b=>b.onclick=()=>open(b.dataset.menu));document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{s[b.dataset.toggle]=!s[b.dataset.toggle];save();b.classList.toggle('on',s[b.dataset.toggle]);});document.querySelectorAll('[data-safe]').forEach(b=>b.onclick=()=>notice(t('Эта функция будет активирована после подключения защищённого backend.','This function will be enabled after the protected backend is connected.')));}
function menu(){screen(t('Меню','Menu'),'<div class="vx-menu-top"><div><span class="vx-kicker">VERTEX</span><h2>'+t('Управление и профиль','Management & profile')+'</h2></div><button class="vx-avatar" data-menu="profile">F</button></div><div class="vx-dashboard"><button data-menu="earnings"><span>'+t('Заработок','Earnings')+'</span><strong>—</strong><small>'+t('После подключения финансов','After finance connection')+'</small></button><button data-menu="analytics"><span>'+t('Аналитика','Analytics')+'</span><strong>'+t('Операции','Operations')+'</strong><small>'+t('Заявки и сервисы','Requests & services')+'</small></button></div><div class="vx-menu-list">'+row('account','⚙','Настройки аккаунта','Account settings')+row('host','⌂','Кабинет хозяина','Host workspace')+row('guide','▤','Материалы для хозяев','Host resources')+row('help','?','Помощь','Help')+row('listing','＋','Создать новое объявление','Create a new listing')+row('team','♙','Команда и доступ','Team & access')+row('company','▦','Сведения о компании','Company information')+row('tax','▥','Налоги','Taxes')+'</div>');}
function account(){screen(t('Настройки аккаунта','Account settings'),back('menu')+'<div class="vx-page-title"><h2>'+t('Настройки аккаунта','Account settings')+'</h2></div><div class="vx-menu-list">'+row('profile','○','Личная информация','Personal information')+row('security','♢','Вход и безопасность','Login & security')+row('privacy','◌','Конфиденциальность','Privacy')+row('notifications','♧','Уведомления','Notifications')+row('payments','▣','Платежи','Payments')+row('translate','◎','Перевод','Translation')+row('booking','⌘','Разрешения на бронирование','Booking permissions')+row('business','▤','Деловые поездки','Business travel')+row('access','✧','Доступная среда','Accessibility')+'</div><div class="vx-divider"></div><div class="vx-menu-list">'+row('company','▦','Сведения о компании','Company information')+row('tax','▥','Налоги','Taxes')+'</div>');}
function profile(){screen(t('Профиль','Profile'),back('menu')+'<div class="vx-profile-card"><div class="vx-big-avatar">F</div><div><h2>Firdavsiy</h2><p>'+t('Хозяин · Tourism & Hospitality','Host · Tourism & Hospitality')+'</p></div><div class="vx-profile-stats"><strong>Views</strong><span>Hotel & Apartments</span></div></div><div class="vx-facts"><p>▣ '+t('Моя работа: Tourism & Hospitality','My work: Tourism & Hospitality')+'</p><p>◎ '+t('Хочу побывать везде, где ещё не был ✈','I want to go everywhere I haven’t been yet ✈')+'</p><p>✧ '+t('Превращаю проживание в полноценное впечатление','I turn stays into experiences')+'</p><p>♢ '+t('Комфорт отеля с ощущением дома','Hotel comfort with the feeling of home')+'</p></div><p class="notice">Views Hotel & Apartments — '+t('профессиональное управление апартаментами и гостеприимство в Ташкенте.','professional apartment management and hospitality in Tashkent.')+'</p>');}
function security(){screen(t('Вход и безопасность','Login & security'),back('account')+'<div class="vx-page-title"><h2>'+t('Вход и безопасность','Login & security')+'</h2></div><div class="vx-tabs"><strong>'+t('Вход','Login')+'</strong><span>'+t('Общий доступ','Shared access')+'</span></div><section class="vx-section"><h3>'+t('Вход','Login')+'</h3><div class="vx-info"><div><strong>'+t('Ключи доступа','Passkeys')+'</strong><p>'+t('Биометрия и системная защита.','Biometrics and system protection.')+'</p></div><button data-safe>'+t('Добавить','Add')+'</button></div><div class="vx-info"><div><strong>'+t('Пароль','Password')+'</strong><p>'+t('Не создан в демо','Not created in demo')+'</p></div><button data-safe>'+t('Создать','Create')+'</button></div></section><section class="vx-section"><h3>'+t('Последние устройства','Recent devices')+'</h3><div class="vx-device">▯ <div><strong>'+t('Это устройство','This device')+'</strong><p>'+t('Локальная демо-сессия Vertex','Local Vertex demo session')+'</p></div></div></section>');}
function notifications(){screen(t('Уведомления','Notifications'),back('account')+'<div class="vx-page-title"><h2>'+t('Уведомления','Notifications')+'</h2></div><div class="vx-tabs"><strong>'+t('Предложения и обновления','Offers & updates')+'</strong><span>'+t('Аккаунт','Account')+'</span></div>'+sw('notifications','Рекомендации и обновления','Recommendations & updates','Аналитика, цены, функции хозяина и важные изменения.','Analytics, pricing, host features and important updates.'));}
function payments(){screen(t('Платежи и выплаты','Payments & payouts'),back('account')+'<div class="vx-page-title vx-title-row"><h2>'+t('Платежи и выплаты','Payments & payouts')+'</h2><span class="vx-currency">$-USD</span></div><section class="vx-section"><h3>'+t('Путешествия','Travel')+'</h3>'+row('payment-methods','▣','Способы оплаты','Payment methods')+row('payment-history','☷','Ваши платежи','Your payments')+'</section><section class="vx-section"><h3>'+t('Прием гостей','Hosting')+'</h3>'+row('payouts','▣','Способы выплаты','Payout methods')+row('transactions','▥','История операций','Transaction history')+'</section><p class="notice">'+t('Реальные платежи и выплаты пока не подключены.','Real payments and payouts are not connected yet.')+'</p>');}
function translation(){screen(t('Перевод','Translation'),back('account')+'<div class="vx-page-title"><h2>'+t('Перевод','Translation')+'</h2><p>'+t('Автоматический перевод описаний, сообщений и интерфейса.','Automatic translation of descriptions, messages and interface.')+'</p></div>'+sw('translation','Автоматический перевод','Automatic translation','Показывать контент на выбранном языке.','Show content in the selected language.'));}
function access(){screen(t('Доступная среда','Accessibility'),back('account')+'<div class="vx-page-title"><h2>'+t('Доступная среда','Accessibility')+'</h2></div>'+sw('loadMore','Загрузить еще','Load more','Кнопка вместо бесконечной прокрутки.','Button instead of infinite scrolling.')+sw('mapZoom','Кнопки масштабирования карты','Map zoom controls','Отдельные элементы масштаба.','Dedicated zoom controls.')+sw('mapMove','Кнопки перемещения по карте','Map movement controls','Кнопки направлений.','Directional controls.'));}
function taxes(){screen(t('Налоги','Taxes'),back('menu')+'<div class="vx-page-title"><h2>'+t('Налоги','Taxes')+'</h2></div><div class="vx-tabs"><strong>'+t('Налогоплательщики','Taxpayers')+'</strong><span>'+t('Налоговые документы','Tax documents')+'</span></div><section class="vx-section"><h3>'+t('Информация о налогоплательщике','Taxpayer information')+'</h3><p>'+t('Чувствительные налоговые данные не собираются в демо.','Sensitive tax data is not collected in the demo.')+'</p><button class="vx-primary" data-safe>'+t('Добавить налоговую информацию','Add tax information')+'</button></section><section class="vx-section"><h3>'+t('НДС','VAT')+'</h3><p>'+t('Данные НДС будут храниться только в защищённом backend.','VAT data will be stored only in a protected backend.')+'</p><button class="vx-primary" data-safe>'+t('Указать номер плательщика НДС','Add VAT number')+'</button></section>');}
const gm={privacy:['Конфиденциальность','Privacy','Локальные данные и будущие разрешения приватности.','Local data and future privacy permissions.'],booking:['Разрешения на бронирование','Booking permissions','Правила подтверждения и управления заявками.','Rules for confirmations and request management.'],business:['Деловые поездки','Business travel','Профили компаний и корпоративные условия.','Company profiles and corporate terms.'],company:['Сведения о компании','Company information','Views Hotel & Apartments · Vertex Group · Ташкент.','Views Hotel & Apartments · Vertex Group · Tashkent.'],help:['Помощь','Help','Гид гостя, поддержка 24/7 и сервисные заявки.','Guest guide, 24/7 support and service requests.'],host:['Кабинет хозяина','Host workspace','Объекты, календарь, заявки и отчёт.','Properties, calendar, requests and report.'],guide:['Материалы для хозяев','Host resources','Инструкции и рабочие материалы Views.','Views instructions and operational resources.'],listing:['Создать новое объявление','Create a new listing','Добавление локального демо-объекта.','Add a local demo property.'],team:['Команда и доступ','Team & access','Роли сотрудников и назначение задач.','Staff roles and task assignment.'],earnings:['Заработок','Earnings','Финансовая аналитика после подключения защищённых данных.','Financial analytics after protected data is connected.'],analytics:['Аналитика','Analytics','Операционная аналитика заявок, объектов и сервисов.','Operational analytics for requests, properties and services.'],'payment-methods':['Способы оплаты','Payment methods','Карта, наличные и криптовалюта — пока без списания.','Card, cash and cryptocurrency — no charges yet.'],'payment-history':['Ваши платежи','Your payments','История появится после подключения acquiring.','History will appear after acquiring is connected.'],payouts:['Способы выплаты','Payout methods','Выплаты требуют защищённого финансового backend.','Payouts require a protected financial backend.'],transactions:['История операций','Transaction history','Реальная финансовая история пока не подключена.','Real financial history is not connected yet.']};
function generic(id,x){const parent=['payment-methods','payment-history','payouts','transactions'].includes(id)?'payments':['privacy','booking','business','access'].includes(id)?'account':'menu';screen(t(x[0],x[1]),back(parent)+'<div class="vx-page-title"><h2>'+t(x[0],x[1])+'</h2><p>'+t(x[2],x[3])+'</p></div><button class="vx-primary" data-safe>'+t('Продолжить внутри Vertex','Continue inside Vertex')+'</button>');}
function notice(msg){screen('Vertex','<p class="notice">'+msg+'</p>'+row('menu','←','Вернуться в меню','Back to menu'));}
function open(id){
  if(id==='menu')return menu();
  if(id==='account')return account();
  if(id==='profile')return profile();
  if(id==='security')return security();
  if(id==='notifications')return notifications();
  if(id==='payments')return payments();
  if(id==='translate')return translation();
  if(id==='access')return access();
  if(id==='tax')return taxes();
  if(id==='host'&&root.VertexHostConsole?.open)return root.VertexHostConsole.open('today');
  if(id==='listing'&&root.VertexRentals?.createListing)return root.VertexRentals.createListing();
  if(id==='analytics'&&root.VertexRentals?.showOwnerReport)return root.VertexRentals.showOwnerReport();
  if(id==='team'&&root.VertexGroup?.requests)return root.VertexGroup.requests();
  if(id==='help'&&root.VertexGuestGuide?.open)return root.VertexGuestGuide.open();
  return generic(id,gm[id]||['Vertex','Vertex','Раздел готовится.','Section is being prepared.']);
}
root.VertexProfileMenu={open,menu};
})(typeof window==='undefined'?globalThis:window);
